set role authenticated;
select set_config('test.org','10000000-0000-4000-8000-000000000001',false);
select set_config('test.permissions','{"customers":{"view":true},"invoices":{"view":true}}',false);
do $$declare result jsonb;s text;begin
 perform set_config('test.permissions','{"customers":{"view":true},"invoices":{"view":true},"purchase_invoices":{"view":true},"projects":{"view":true},"tasks":{"view":true},"process_runs":{"view":true},"counterparty_bot_groups":{"view":true},"sms_delivery_reports":{"view":true},"email_delivery_reports":{"view":true},"voip_call_reports":{"view":true}}',true);
 foreach s in array array['purchases','projects','tasks','processes','groups','sms','email','calls']loop
  result:=public.read_call_contact_history('customers','40000000-0000-4000-8000-000000000001',s,0);
  if result->>'count'<>'0' then raise exception 'empty authorized section is inconsistent: %',s;end if;
 end loop;
 result:=public.read_call_contact_history('customers','40000000-0000-4000-8000-000000000001','invoices',0);
 if (result->>'count')::int<>21 or jsonb_array_length(result->'rows')<>20 or not (result->>'hasMore')::boolean then raise exception 'page treated as complete history';end if;
 if result->'rows'->0->>'name'<>'فاکتور 21' then raise exception 'newest activity ordering failed';end if;
 if (result->'summary'->>'settled')::int<>1 or (result->'summary'->>'completedAndSettled')::int<>1 then raise exception 'invoice summary includes wrong tenant/deleted rows';end if;
 if exists(select 1 from jsonb_array_elements(result->'rows')r where r->>'name'='نباید دیده شود')then raise exception 'foreign invoice leaked';end if;
 result:=public.read_call_contact_history('customers','40000000-0000-4000-8000-000000000001','invoices',20);
 if jsonb_array_length(result->'rows')<>1 or (result->>'hasMore')::boolean then raise exception 'older page unavailable';end if;
 perform set_config('test.permissions','{"customers":{"view":true},"invoices":{"view":true,"fields":{"remaining_balance":false,"payments":false}}}',true);
 result:=public.read_call_contact_history('customers','40000000-0000-4000-8000-000000000001','invoices',0);
 if result->'rows'->0?'remaining_balance' or result->'rows'->0?'payments' or result->'summary'<>'null'::jsonb then raise exception 'field restrictions leaked through summary';end if;
 perform set_config('test.user','20000000-0000-4000-8000-000000000001',true);
 perform set_config('test.permissions','{"customers":{"view":true},"invoices":{"view":true,"record_scope":"own"}}',true);
 result:=public.read_call_contact_history('customers','40000000-0000-4000-8000-000000000001','invoices',0);
 if (result->>'count')::int<>3 then raise exception 'own record scope bypassed';end if;
 perform set_config('test.permissions','{"customers":{"view":true,"record_scope":"own"},"invoices":{"view":true}}',true);
 result:=public.search_call_contact_identities('مخاطب',null);
 if jsonb_array_length(result)<>1 then raise exception 'identity scope applied after page limit';end if;
 result:=public.search_call_contact_identities('09120000000','9120000000');
 if jsonb_array_length(result)<>1 then raise exception 'existing manual phone identity binding lost';end if;
 perform set_config('test.permissions','{"customers":{"view":true},"invoices":{"view":true,"view_conditions":{"conditions_all":[{"field":"status","operator":"eq","value":"settled"}]}}}',true);
 result:=public.read_call_contact_history('customers','40000000-0000-4000-8000-000000000001','invoices',0);
 if (result->>'count')::int<>1 then raise exception 'organization-defined view conditions not respected';end if;
 perform set_config('test.permissions','{"customers":{"view":true},"invoices":{"view":true,"view_conditions":{"conditions_all":[{"field":"related.customer","operator":"eq","value":"blocked"}]}}}',true);
 result:=public.read_call_contact_history('customers','40000000-0000-4000-8000-000000000001','invoices',0);
 if (result->>'count')::int<>0 then raise exception 'unsupported view conditions ignored';end if;
 perform set_config('test.org','',true);
 begin
  perform public.read_call_contact_history('customers','40000000-0000-4000-8000-000000000001','invoices',0);
  raise exception 'null tenant accepted';
 exception when others then if sqlerrm<>'contact_scope_required' then raise;end if;end;
end$$;
reset role;
